import json
from pathlib import Path

ids = set(json.loads(
    Path("blocking_locs/blocking_locs.json").read_text()
))

max_id = max(ids)
bits = bytearray((max_id // 8) + 1)

for loc_id in ids:
    bits[loc_id // 8] |= 1 << (loc_id % 8)

hex_data = bits.hex()

lines = [
    "-- Generated by pack_blocking_locs.py",
    "-- Cache Locs with blocks_movement = true",
    "",
    "local data = table.concat({",
]

for i in range(0, len(hex_data), 128):
    lines.append(f'    "{hex_data[i:i+128]}",')

lines.extend([
    "})",
    "",
    'data = data:gsub("..", function(hex)',
    "    return string.char(tonumber(hex, 16))",
    "end)",
    "",
    "local M = {}",
    "",
    "function M.contains(id)",
    '    if type(id) ~= "number" or id < 0 then',
    "        return false",
    "    end",
    "    local byte = data:byte((id // 8) + 1)",
    "    return byte ~= nil and (byte & (1 << (id % 8))) ~= 0",
    "end",
    "",
    "return M",
])

output = Path("blocking_locs/packed_blocking_locs.lua")
output.write_text("\n".join(lines))

print(f"Blocking Locs: {len(ids):,}")
print(f"Highest Loc ID: {max_id:,}")
print(f"Runtime bitset: {len(bits) / 1024:.2f} KiB")
print(f"Lua file: {output.stat().st_size / 1024:.2f} KiB")